import Foundation
import CryptoKit

// MARK: - Distributed Cache Client with Audit Logging

struct CacheNode: Hashable {
    let host: String
    let port: Int
    let region: String
}

class AuditLogger {
    private let logQueue = DispatchQueue(label: "audit.log.queue")
    private var entries: [(timestamp: Date, operation: String, keyHash: String)] = []

    func log(operation: String, keyHash: String) {
        logQueue.async { [weak self] in
            self?.entries.append((Date(), operation, keyHash))
        }
    }

    func getEntries() -> [(timestamp: Date, operation: String, keyHash: String)] {
        return logQueue.sync { entries }
    }
}

class KeyDerivationService {
    private let masterSecret: SymmetricKey
    private let cachePurpose: String

    init(masterSecret: Data, purpose: String) {
        self.masterSecret = SymmetricKey(data: masterSecret)
        self.cachePurpose = purpose
    }

    /// Derives a per-node encryption key using HKDF
    func deriveNodeKey(for node: CacheNode, epoch: UInt64) -> SymmetricKey {
        let context = buildContext(node: node, epoch: epoch)
        let derivedKey = HKDF<SHA256>.deriveKey(
            inputKeyMaterial: masterSecret,
            salt: Data(cachePurpose.utf8),
            info: context,
            outputByteCount: 32
        )
        return derivedKey
    }

    private func buildContext(node: CacheNode, epoch: UInt64) -> Data {
        // Context includes host, port, and region for full node differentiation
        var ctx = Data()
        ctx.append(Data(node.host.utf8))
        ctx.append(Data(":".utf8))
        ctx.append(Data(String(node.port).utf8))
        ctx.append(Data(":".utf8))
        ctx.append(Data(node.region.utf8))
        ctx.append(Data(":".utf8))
        // Epoch for key rotation - truncated to rotation window
        let rotationWindow: UInt64 = 3600
        let windowEpoch = epoch / rotationWindow
        withUnsafeBytes(of: windowEpoch.bigEndian) { ctx.append(contentsOf: $0) }
        return ctx
    }
}

class DistributedCacheClient {
    private let nodes: [CacheNode]
    private let keyService: KeyDerivationService
    private let auditLogger: AuditLogger
    private let consistentHash: ConsistentHashRing

    init(nodes: [CacheNode], masterSecret: Data, purpose: String) {
        self.nodes = nodes
        self.keyService = KeyDerivationService(masterSecret: masterSecret, purpose: purpose)
        self.auditLogger = AuditLogger()
        self.consistentHash = ConsistentHashRing(nodes: nodes)
    }

    func put(key: String, value: Data) throws {
        let targetNode = consistentHash.getNode(for: key)
        let epoch = currentEpoch()
        let encryptionKey = keyService.deriveNodeKey(for: targetNode, epoch: epoch)

        let nonce = try AES.GCM.Nonce(data: buildNonce(key: key, epoch: epoch))
        let sealed = try AES.GCM.seal(value, using: encryptionKey, nonce: nonce)

        let keyHash = SHA256.hash(data: Data(key.utf8)).description
        auditLogger.log(operation: "PUT", keyHash: keyHash)

        // Simulate network send
        let _ = CacheWireMessage(node: targetNode, payload: sealed.combined!, epoch: epoch)
    }

    func get(key: String) throws -> Data? {
        let targetNode = consistentHash.getNode(for: key)
        let epoch = currentEpoch()
        let encryptionKey = keyService.deriveNodeKey(for: targetNode, epoch: epoch)

        let keyHash = SHA256.hash(data: Data(key.utf8)).description
        auditLogger.log(operation: "GET", keyHash: keyHash)

        // Simulate network receive - in production would fetch from node
        return nil
    }

    private func buildNonce(key: String, epoch: UInt64) -> Data {
        // Nonce derived from key content and epoch window for uniqueness
        var material = Data(key.utf8)
        let rotationWindow: UInt64 = 3600
        let windowEpoch = epoch / rotationWindow
        withUnsafeBytes(of: windowEpoch.bigEndian) { material.append(contentsOf: $0) }
        let hash = SHA256.hash(data: material)
        return Data(hash.prefix(12))
    }

    private func currentEpoch() -> UInt64 {
        return UInt64(Date().timeIntervalSince1970)
    }
}

class ConsistentHashRing {
    private let nodes: [CacheNode]
    private let virtualNodes: Int = 150
    private var ring: [(hash: UInt64, node: CacheNode)] = []

    init(nodes: [CacheNode]) {
        self.nodes = nodes
        buildRing()
    }

    private func buildRing() {
        for node in nodes {
            for i in 0..<virtualNodes {
                let key = "\(node.host):\(node.port)#\(i)"
                let hash = fnv1a(Data(key.utf8))
                ring.append((hash, node))
            }
        }
        ring.sort { $0.hash < $1.hash }
    }

    func getNode(for key: String) -> CacheNode {
        let hash = fnv1a(Data(key.utf8))
        for entry in ring {
            if entry.hash >= hash {
                return entry.node
            }
        }
        return ring.first!.node
    }

    private func fnv1a(_ data: Data) -> UInt64 {
        var hash: UInt64 = 14695981039346656037
        for byte in data {
            hash ^= UInt64(byte)
            hash &*= 1099511628211
        }
        return hash
    }
}

struct CacheWireMessage {
    let node: CacheNode
    let payload: Data
    let epoch: UInt64
}
